#!/usr/bin/env Rscript
args<-commandArgs(TRUE);project<-normalizePath(if(length(args))args[1]else'paper19opp-revision2');p<-file.path(project,'upr_robustness','ranking');out<-file.path(p,'canonical94_projection');dir.create(out,showWarnings=FALSE);canon<-file.path(project,'upr_robustness','modules','canonical_Hallmark94');src<-file.path(project,'reconstruction','cross_dataset','phase2_upr_rpe1');.libPaths(c(file.path(dirname(project),'.Rlib'),.libPaths()));suppressPackageStartupMessages({library(data.table);library(digest)})
set.seed(2026110608);needed<-c('weighted_median','wm','qtstat','ndcg','listmetrics','getlists');for(e in parse(file.path(p,'analyze_rank_robustness.R')))if(is.call(e)&&identical(e[[1]],as.name('<-'))&&is.symbol(e[[2]])&&as.character(e[[2]])%in%needed)eval(e)
qa<-fread(file.path(canon,'reference90_reconstruction_QA.tsv'));stopifnot(all(qa$passed),nrow(qa)==4L)
f<-file.path(canon,c('technical_addendum.txt','technical_addendum_lock.tsv','execution_lock_manifest.tsv','reference90_reconstruction_QA.tsv','K562_gene_effects.tsv.gz','RPE1_gene_effects.tsv.gz','RPE1_GEM_effects.tsv.gz'));fwrite(data.table(file=sub(paste0('^',project,'/'),'',f),sha256=vapply(f,digest,'',file=TRUE,algo='sha256')),file.path(out,'input_hashes.tsv'),sep='\t');writeLines(paste('First canonical94 effect read UTC',format(Sys.time(),tz='UTC',usetz=TRUE)),file.path(out,'first_read.txt'))
d<-fread(file.path(canon,'RPE1_gene_effects.tsv.gz'));gg<-fread(file.path(canon,'RPE1_GEM_effects.tsv.gz'));sd<-fread(file.path(canon,'K562_gene_effects.tsv.gz'));stopifnot(all(d$axis=='Hallmark_UPR94_canonical'),all(sd$axis=='Hallmark_UPR94_canonical'))
meta<-fread(file.path(src,'source_rank_inputs.tsv'));cohorts<-list(all438=sort(meta$gene),complete370=sort(fread(file.path(src,'complete_covariate_gene_roster.tsv'))$gene));lists<-list(all438=getlists(fread(file.path(src,'all_source_comparator_rankings.tsv'))[available==TRUE]),complete370=getlists(fread(file.path(src,'complete_covariate_source_rankings.tsv')),rankcol='rank_cc'));bg<-list(all438=fread(file.path(src,'frozen_background_matches.tsv'))[list=='UPR'],complete370=fread(file.path(src,'complete_covariate_background_matches.tsv'))[list=='CC_UPR'])
state<-readRDS(file.path(project,'reconstruction','upr_rpe1_validation','phase2_statistical_state.rds'));signs<-state$primary$validation_wild$wild_signs;gems<-state$primary$validation_wild$gem_labels;qmap<-fread(file.path(p,'source_quintile_membership.tsv'))[cohort=='all438'];qall<-setNames(qmap$quintile,qmap$gene)
metrics<-list();comparisons<-list();groups<-list();trends<-list();backgrounds<-list();mi<-ci<-gi<-ti<-bi<-0L
qci<-function(v)as.numeric(quantile(v,c(.025,.975),na.rm=TRUE))
for(mm in c('exact_Lminus_target','fixed_L6780')){
 dd<-d[mode==mm&gene%in%cohorts$all438];stopifnot(nrow(dd)==438L,all(dd$estimable));yall<-setNames(dd$delta_z,dd$gene)[cohorts$all438];xx<-setNames(sd[mode==mm]$delta_z,sd[mode==mm]$gene);gr<-gg[mode==mm&gene%in%cohorts$all438];ck<-gr[,.(p=weighted.mean(contrast_z,n_target),n=sum(n_target)),by=gene];total<-setNames(ck$n,ck$gene);stopifnot(max(abs(setNames(ck$p,ck$gene)[names(yall)]-yall))<1e-8);R<-matrix(0,438,length(gems),dimnames=list(names(yall),gems));R[cbind(match(gr$gene,names(yall)),match(gr$gem,gems))]<-gr$n_target/total[gr$gene]*(gr$contrast_z-yall[gr$gene]);wildall<-sweep(R%*%signs,1,yall,'+')
 for(n in names(cohorts)){
  g<-cohorts[[n]];y<-yall[g];wild<-wildall[g,,drop=FALSE];W<-readRDS(file.path(p,paste0('gene_bootstrap_weights_',n,'.rds')))[,g,drop=FALSE];ll<-lists[[n]];q<-qall[g]
  for(m in names(ll))for(k in c(10L,20L)){
   s<-head(ll[[m]],k);ia<-match(s,g);v<-listmetrics(y,s,k);pb<-rowSums(sweep(W[,ia,drop=FALSE],2,y[s]>0,'*'))/rowSums(W[,ia,drop=FALSE]);tp<-colMeans(wild[ia,,drop=FALSE]>0);tn<-apply(wild,2,function(z){names(z)<-g;ndcg(z,s,k)});mi<-mi+1L;metrics[[mi]]<-data.table(axis='Hallmark_UPR94_canonical',mode=mm,cohort=n,method=m,K=k,Precision=v['Precision'],NDCG=v['NDCG'],mean_signed=v['mean'],median_signed=v['median'],mean_absolute=mean(abs(y[s])),cohort_positive=mean(y>0),source_RPE_same_readout_sign_concordance=mean(sign(xx[s])==sign(y[s])),Precision_gene_low=qci(pb)[1],Precision_gene_high=qci(pb)[2],Precision_technical_low=qci(tp)[1],Precision_technical_high=qci(tp)[2],NDCG_technical_low=qci(tn)[1],NDCG_technical_high=qci(tn)[2])
  }
  for(reference in setdiff(names(ll),'UPR_priority'))for(k in c(10L,20L)){
   a<-head(ll$UPR_priority,k);b<-head(ll[[reference]],k);ia<-match(a,g);ib<-match(b,g);pb<-rowSums(sweep(W[,ia,drop=FALSE],2,y[a]>0,'*'))/rowSums(W[,ia,drop=FALSE])-rowSums(sweep(W[,ib,drop=FALSE],2,y[b]>0,'*'))/rowSums(W[,ib,drop=FALSE]);disc<-1/log2(seq_len(k)+1);coef<-numeric(length(g));coef[ia]<-coef[ia]+disc;coef[ib]<-coef[ib]-disc;ideal<-sum(sort(pmax(y,0),decreasing=TRUE)[seq_len(k)]*disc);nb<-as.numeric(W%*%(coef*pmax(y,0)))/ideal;tp<-colMeans(wild[ia,,drop=FALSE]>0)-colMeans(wild[ib,,drop=FALSE]>0);tn<-apply(wild,2,function(z){names(z)<-g;ndcg(z,a,k)-ndcg(z,b,k)});ci<-ci+1L;comparisons[[ci]]<-data.table(mode=mm,cohort=n,method='UPR_priority',reference=reference,K=k,endpoint=c('Precision','NDCG'),difference=c(mean(y[a]>0)-mean(y[b]>0),ndcg(y,a,k)-ndcg(y,b,k)),gene_low=c(qci(pb)[1],qci(nb)[1]),gene_high=c(qci(pb)[2],qci(nb)[2]),technical_low=c(qci(tp)[1],qci(tn)[1]),technical_high=c(qci(tp)[2],qci(tn)[2]),conditional_observed_IDCG=ideal)
  }
  for(i in 1:5){v<-y[q==i];bm<-apply(W[,q==i,drop=FALSE],1,function(w)wm(v,w));gi<-gi+1L;groups[[gi]]<-data.table(mode=mm,cohort=n,source_groups='current90_primary438',quintile=i,genes=length(v),mean_signed=mean(v),median_signed=median(v),positive_fraction=mean(v>0),mean_gene_low=qci(bm)[1],mean_gene_high=qci(bm)[2])}
  point<-qtstat(y,q);qb<-t(apply(W,1,function(w)qtstat(y,q,w)));qw<-t(apply(wild,2,function(z)qtstat(z,q)));ti<-ti+1L;trends[[ti]]<-data.table(mode=mm,cohort=n,source_groups='current90_primary438',endpoint=names(point),estimate=point,gene_low=apply(qb,2,quantile,.025),gene_high=apply(qb,2,quantile,.975),technical_low=apply(qw,2,quantile,.025),technical_high=apply(qw,2,quantile,.975))
  for(k in c(10L,20L)){
   bb<-bg[[n]];if(k==10)bb<-bb[Top10==TRUE];a<-unique(bb$selected_gene);b<-bb$background_gene;ia<-match(a,g);ib<-match(b,g);stopifnot(length(a)==k,length(b)==5*k);for(e in c('signed_mean_gap','absolute_mean_gap','positive_gap')){v<-if(e=='signed_mean_gap')y else if(e=='absolute_mean_gap')abs(y)else as.numeric(y>0);names(v)<-g;ww<-if(e=='signed_mean_gap')wild else if(e=='absolute_mean_gap')abs(wild)else wild>0;boot<-rowSums(sweep(W[,ia,drop=FALSE],2,v[ia],'*'))/rowSums(W[,ia,drop=FALSE])-rowSums(sweep(W[,ib,drop=FALSE],2,v[ib],'*'))/rowSums(W[,ib,drop=FALSE]);tech<-colMeans(ww[ia,,drop=FALSE])-colMeans(ww[ib,,drop=FALSE]);byset<-bb[,.(delta=v[selected_gene[1]]-mean(v[background_gene])),by=selected_gene]$delta;sb<-replicate(2000,mean(byset[sample.int(k,k,replace=TRUE)]));bi<-bi+1L;backgrounds[[bi]]<-data.table(mode=mm,cohort=n,K=k,endpoint=e,estimate=mean(v[a])-mean(v[b]),gene_low=qci(boot)[1],gene_high=qci(boot)[2],matched_set_low=qci(sb)[1],matched_set_high=qci(sb)[2],technical_low=qci(tech)[1],technical_high=qci(tech)[2])}
  }
 }
 cat('Completed canonical94 current-list projection',mm,'\n');flush.console()
}
for(pair in list(c('metrics','canonical94_current_fixed_list_metrics.tsv'),c('comparisons','canonical94_paired_current_method_comparisons.tsv'),c('groups','canonical94_current_quintile_groups.tsv'),c('trends','canonical94_current_quintile_trends.tsv'),c('backgrounds','canonical94_current_matched_gap_intervals.tsv')))fwrite(rbindlist(get(pair[1])),file.path(out,pair[2]),sep='\t',na='NA')
writeLines(capture.output(sessionInfo()),file.path(out,'sessionInfo.txt'));writeLines(c('Identifier-coverage sensitivity only; original90 source ranks, groups and results remain unchanged.','No94source reranking, new formal P family, parent-null calibration or new independent validation.','Point metrics and conditional intervals use the same definitions and resampling units as the existing ranking extension.'),file.path(out,'scope.txt'));cat('Canonical94 current-list projection complete',format(Sys.time(),tz='UTC',usetz=TRUE),'\n')
